import{_ as a,o as n,c as s,a1 as t}from"./chunks/framework.Cv8QbFmh.js";const k=JSON.parse('{"title":"Installing Manjaro on an Optimus Laptop - Black Screens, a Portable Monitor, Random Freezes, and the Move to Wayland","description":"A full troubleshooting record of a fresh Manjaro KDE install on an ASUS TUF Gaming A14 (AMD iGPU + RTX 5060) - from GRUB black screen and mismatched NVIDIA modules to AMDGPU fence deadlocks on X11; the switch to Wayland fixed the greeter black screen and the fence deadlocks, but not every freeze.","frontmatter":{"title":"Installing Manjaro on an Optimus Laptop - Black Screens, a Portable Monitor, Random Freezes, and the Move to Wayland","description":"A full troubleshooting record of a fresh Manjaro KDE install on an ASUS TUF Gaming A14 (AMD iGPU + RTX 5060) - from GRUB black screen and mismatched NVIDIA modules to AMDGPU fence deadlocks on X11; the switch to Wayland fixed the greeter black screen and the fence deadlocks, but not every freeze.","date":"2026-10-01T00:00:00.000Z","tags":["Manjaro","NVIDIA","AMD","KDE","Wayland","Linux"],"sidebar":false},"headers":[],"relativePath":"blog/2026-10-01-manjaro-install-on-an-optimus-laptop.md","filePath":"blog/2026-10-01-manjaro-install-on-an-optimus-laptop.md"}'),i={name:"blog/2026-10-01-manjaro-install-on-an-optimus-laptop.md"};function o(l,e,r,d,h,p){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="installing-manjaro-on-an-optimus-laptop-black-screens-a-portable-monitor-random-freezes-and-the-move-to-wayland" tabindex="-1">Installing Manjaro on an Optimus Laptop: Black Screens, a Portable Monitor, Random Freezes, and the Move to Wayland <a class="header-anchor" href="#installing-manjaro-on-an-optimus-laptop-black-screens-a-portable-monitor-random-freezes-and-the-move-to-wayland" aria-label="Permalink to &quot;Installing Manjaro on an Optimus Laptop: Black Screens, a Portable Monitor, Random Freezes, and the Move to Wayland&quot;">​</a></h1><p><code>2026-10-01</code> · Manjaro · NVIDIA · AMD · Wayland</p><p>This post records everything I went through when replacing Windows 11 with a Manjaro KDE dual-boot on an ASUS TUF Gaming A14 (FA401KM) laptop. The hardware detail that caused most of the pain: it is an <strong>Optimus hybrid-graphics machine</strong> - an AMD Radeon 860M iGPU plus an NVIDIA RTX 5060 Laptop dGPU - and the <strong>internal panel is wired to the iGPU</strong>, not the dGPU.</p><h2 id="installation-media-and-process" tabindex="-1">Installation Media and Process <a class="header-anchor" href="#installation-media-and-process" aria-label="Permalink to &quot;Installation Media and Process&quot;">​</a></h2><p>The install itself was uneventful, following my usual flow:</p><ol><li>Prepare a Ventoy USB drive and drop the Manjaro KDE Plasma ISO onto it.</li><li>Press <code>F2</code> during boot to enter the BIOS, then boot the USB drive from <code>Save &amp; Exit -&gt; Boot Override</code>.</li><li>In Ventoy, boot the image in normal mode (grub2 mode is the fallback if normal mode fails).</li><li>In the live environment, set tz to <code>Asia/Shanghai</code> and lang to <code>zh_CN</code>, and boot with open-source drivers.</li><li>In the installer: erase the full disk, choose swap <strong>with</strong> hibernation (recommended for laptops), and skip the office suite.</li></ol><p>After installation finished, I removed the USB drive and rebooted. The GRUB menu appeared and listed both Windows and Manjaro. Choosing Manjaro gave a <strong>black screen</strong> - and that is where the real work began.</p><h2 id="first-black-screen-no-nvidia-driver-for-rtx-5060" tabindex="-1">First Black Screen: No NVIDIA Driver for RTX 5060 <a class="header-anchor" href="#first-black-screen-no-nvidia-driver-for-rtx-5060" aria-label="Permalink to &quot;First Black Screen: No NVIDIA Driver for RTX 5060&quot;">​</a></h2><p><code>Ctrl + Alt + F3</code> still switched to a TTY, which meant the kernel booted fine and the problem was in the graphics stack. Checking the GPU and loaded modules:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;vga|3d&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lsmod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia</span></span></code></pre></div><p>Only <code>nvidia_wmi_ec_backlight</code> (a backlight helper, not a driver) and nouveau were loaded. The RTX 5060 is a Blackwell-architecture GPU that nouveau cannot drive, so the plan was to install the proprietary driver:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mhwd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nonfree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0300</span></span></code></pre></div><h2 id="no-network-usb-tethering-from-a-phone" tabindex="-1">No Network: USB Tethering from a Phone <a class="header-anchor" href="#no-network-usb-tethering-from-a-phone" aria-label="Permalink to &quot;No Network: USB Tethering from a Phone&quot;">​</a></h2><p>The machine had no Wi-Fi configured yet, so I tethered through an Android phone - Linux has built-in <code>rndis_host</code>/<code>cdc_ncm</code> drivers, so USB tethering works with zero setup:</p><ol><li>Connect the phone with a data cable and enable USB tethering.</li><li>Check that a <code>usb0</code> interface appears with <code>ip a</code>.</li><li>Let NetworkManager pick it up and verify with <code>ping</code>.</li></ol><p>One caveat from this incident: the phone kept disconnecting and reconnecting (visible as repeated <code>USB disconnect</code> lines in <code>dmesg</code>). Mid-download disconnects are what caused the half-installed states later, so use a good cable and a native USB port.</p><h2 id="mhwd-failed-broken-mirrors-and-dns" tabindex="-1">mhwd Failed: Broken Mirrors and DNS <a class="header-anchor" href="#mhwd-failed-broken-mirrors-and-dns" aria-label="Permalink to &quot;mhwd Failed: Broken Mirrors and DNS&quot;">​</a></h2><p>The first driver installation failed with <code>Error: pacman failed!</code>. The downloaded mirror list was unusable - pacman had picked a mirror in Uruguay running at less than 1 byte per second, and the other mirrors failed DNS resolution. The fix:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;nameserver 223.5.5.5&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/resolv.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman-mirrors</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> China</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Syy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mhwd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pci</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nonfree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0300</span></span></code></pre></div><p>After switching to Chinese mirrors (TUNA/USTC/SJTU) and setting a working DNS server, the ~500 MB driver download finished in minutes.</p><h2 id="loadkmap-short-read-and-a-module-that-was-not-there" tabindex="-1"><code>loadkmap: short read</code>, and a Module That Was Not There <a class="header-anchor" href="#loadkmap-short-read-and-a-module-that-was-not-there" aria-label="Permalink to &quot;\`loadkmap: short read\`, and a Module That Was Not There&quot;">​</a></h2><p>After the driver installed, the next boot showed <code>loadkmap: short read</code>. That message itself is a benign initramfs keymap warning (see <a href="./2026-08-11-manjaro-nvidia-black-screen.html">the earlier post about this message</a> for a case where it mattered). The real failure was still SDDM:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sddm[755]: Failed to read display number from pipe</span></span>
<span class="line"><span>Could not start Display server on vt 2</span></span></code></pre></div><p>And the module was missing:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modprobe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># modprobe: FATAL: Module nvidia not found in directory /lib/modules/7.1.8-1-MANJARO</span></span></code></pre></div><p>Two usual suspects were eliminated quickly:</p><ul><li><strong>Secure Boot</strong>: already disabled in the BIOS.</li><li><strong>Driver/userland version mismatch</strong>: <code>linux71-nvidia-open 610.57.04-6</code> matched <code>nvidia-utils 610.57.04-1</code> exactly.</li></ul><p>The actual cause showed up when listing the files shipped by the driver package:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Ql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux71-nvidia-open</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\\.ko&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># /usr/lib/modules/7.1.9-1-MANJARO/extramodules/nvidia-drm.ko.zst</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ...</span></span></code></pre></div><p>The driver modules were compiled for kernel <strong>7.1.9</strong>, while the installed and running kernel was <strong>7.1.8</strong>. pacman considered the package installed, but modprobe for the running kernel found nothing. Reinstalling the driver package alone could not help. The fix was a full upgrade to align the kernel with the modules:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Syu</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span></code></pre></div><p>After booting 7.1.9, <code>modprobe nvidia</code> succeeded and <code>nvidia-smi</code> printed the RTX 5060 table.</p><h2 id="second-black-screen-x-rendering-fine-nothing-on-the-internal-panel" tabindex="-1">Second Black Screen: X Rendering Fine, Nothing on the Internal Panel <a class="header-anchor" href="#second-black-screen-x-rendering-fine-nothing-on-the-internal-panel" aria-label="Permalink to &quot;Second Black Screen: X Rendering Fine, Nothing on the Internal Panel&quot;">​</a></h2><p>With the driver working, the next boot still ended at a black screen with a cursor in the top-left corner. <code>nvidia-smi</code> even showed <code>Xorg</code> and <code>sddm-greeter-qt6</code> running on the GPU - X was rendering, but the picture never reached the internal panel.</p><p>Enumerating the DRM connectors explained why:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>card0-DP-8, card0-eDP-2, card0-HDMI-A-2        # the NVIDIA dGPU</span></span>
<span class="line"><span>card1-DP-1..7, card1-eDP-1, card1-HDMI-A-1     # the AMD iGPU</span></span>
<span class="line"><span>card1-eDP-1: connected</span></span></code></pre></div><p>The internal panel (<code>eDP-1</code>) hangs off the <strong>AMD iGPU</strong>, while mhwd had generated a legacy <code>/etc/X11/xorg.conf.d/90-mhwd.conf</code> - an old single-GPU <code>nvidia-xconfig</code> template with no <code>OutputClass</code>, no PRIME reverse-PRIME chain, and no <code>AllowEmptyInitialConfiguration</code>. X rendered on the dGPU with no path to the iGPU-attached panel.</p><p>What fixed the X11 side:</p><ol><li>Move the legacy config away: <code>sudo mv /etc/X11/xorg.conf.d/90-mhwd.conf /etc/X11/xorg.conf.d/90-mhwd.conf.bak</code></li><li>Make sure <code>nvidia_drm</code> modesetting is enabled (<code>options nvidia_drm modeset=1</code> in <code>/etc/modprobe.d/</code>; current nvidia-open drivers enable it by default).</li><li>Clean the stale blacklists (<code>blacklist drm</code>, <code>blacklist ttm</code>, <code>blacklist drm_kms_helper</code>) that mhwd had left in <code>/etc/modprobe.d/mhwd-gpu.conf</code> - those are leftovers for ancient 390xx drivers and are actively harmful on nvidia-open.</li><li><code>sudo mkinitcpio -P</code> and reboot.</li></ol><h2 id="the-portable-monitor-stage" tabindex="-1">The Portable Monitor Stage <a class="header-anchor" href="#the-portable-monitor-stage" aria-label="Permalink to &quot;The Portable Monitor Stage&quot;">​</a></h2><p>Even after that, SDDM still showed nothing on the internal panel. The decisive experiment: plug in a portable external monitor over HDMI. The login screen appeared <strong>on the external monitor only</strong> - and after logging into KDE, the internal panel lit up too.</p><p>That behavior pinned down the last piece: the greeter only activated X&#39;s default output (the dGPU&#39;s HDMI), while KDE&#39;s kwin enables every detected output once the session starts. The full render-to-panel chain was working; the greeter stage was the only gap.</p><h2 id="random-freezes-on-x11-amdgpu-fence-deadlock" tabindex="-1">Random Freezes on X11: AMDGPU Fence Deadlock <a class="header-anchor" href="#random-freezes-on-x11-amdgpu-fence-deadlock" aria-label="Permalink to &quot;Random Freezes on X11: AMDGPU Fence Deadlock&quot;">​</a></h2><p>The story was not over. On X11 the machine froze repeatedly: the desktop would lock up mid-typing, no keyboard shortcuts responded, and only a long-press power-off recovered it. Two telling patterns:</p><ul><li>A day spent on the portable monitor alone: no freeze at all.</li><li>During a freeze, the <strong>internal panel froze first</strong>; the portable monitor sometimes kept working for a while.</li></ul><p>Suspects tested and ruled out along the way: setting both AC and battery suspend actions to &quot;nothing&quot; in KDE did not prevent freezes after unplugging the monitor, and freezes also reproduced on boots where RustDesk had never been started. As a temporary mitigation, <code>kscreen_backend_launcher</code> could be stopped so KDE stopped re-submitting the display configuration, but already-blocked kernel threads only cleared after a reboot.</p><p>The kernel logs identified the deadlock:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INFO: task kworker/u64:* blocked for more than 122 seconds.</span></span>
<span class="line"><span>Workqueue: events_unbound commit_work</span></span>
<span class="line"><span>amdgpu_display_get_crtc_scanoutpos</span></span>
<span class="line"><span>dma_fence_default_wait</span></span>
<span class="line"><span>drm_atomic_helper_wait_for_fences</span></span>
<span class="line"><span>commit_tail</span></span></code></pre></div><p>Every freeze followed the same timeline: KDE X11/KScreen restored the dual-screen layout via XRandR right after login, the AMDGPU DRM atomic commit waited on a DMA fence that never completed, the display workqueue thread went into uninterruptible <code>D</code> state, and the iGPU-driven internal panel stopped updating first (the dGPU-driven external panel survived a bit longer).</p><h2 id="switching-sddm-and-the-session-to-wayland" tabindex="-1">Switching SDDM and the Session to Wayland <a class="header-anchor" href="#switching-sddm-and-the-session-to-wayland" aria-label="Permalink to &quot;Switching SDDM and the Session to Wayland&quot;">​</a></h2><p>Instead of fighting X11 PRIME edge cases and the fence deadlock further, I moved the display manager and session to Wayland, which bypasses the reverse-PRIME chain entirely:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sddm.conf.d/99-wayland.conf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[General]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DisplayServer=wayland</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span></code></pre></div><p>After a reboot, SDDM showed the login screen on the internal panel without any external monitor, and logging into the Plasma (Wayland) session just worked. The same dual-screen layout no longer triggered any <code>dma_fence</code> hangs, blocked tasks, or GPU resets - that class of X11 deadlock was gone for good.</p><h2 id="takeaways" tabindex="-1">Takeaways <a class="header-anchor" href="#takeaways" aria-label="Permalink to &quot;Takeaways&quot;">​</a></h2><ul><li><strong>Check the display topology first on hybrid laptops.</strong> <code>ls /sys/class/drm/card*/</code> tells you which GPU owns the internal panel; on this machine the panel is on the iGPU, so every X11 assumption &quot;the NVIDIA card drives the screen&quot; was wrong from the start.</li><li><strong><code>modprobe: FATAL: Module not found</code> with an installed driver package usually means kernel/module directory mismatch.</strong> List the package files with <code>pacman -Ql</code> and compare the version directory against <code>uname -r</code>; a full <code>pacman -Syu</code> is the fix, not reinstalling the driver.</li><li><strong>A black screen with a live TTY is a userspace graphics problem, not a broken install.</strong> Nomodeset in GRUB is a fine one-boot diagnostic.</li><li><strong>USB tethering is the fastest way online on a fresh install</strong> - but an unstable cable produces half-finished transactions that cause exactly the kind of &quot;installed but missing&quot; states seen above.</li><li><strong>On Optimus laptops with the panel on the iGPU, Wayland is the path of least resistance.</strong> It removed both the greeter black screen and the X11 AMDGPU fence deadlocks.</li><li>The <code>nvidia_wmi_ec_backlight</code> ACPI errors visible in the logs were noise throughout and unrelated to any of the failures above (they became their own story on 2026-09, when EC backlight control actually broke).</li></ul><h2 id="epilogue-2026-10-freezes-are-not-entirely-gone" tabindex="-1">Epilogue (2026-10): Freezes Are Not Entirely Gone <a class="header-anchor" href="#epilogue-2026-10-freezes-are-not-entirely-gone" aria-label="Permalink to &quot;Epilogue (2026-10): Freezes Are Not Entirely Gone&quot;">​</a></h2><p>One correction to the claim above: what disappeared with Wayland was that one class of deadlock. In 2026-10 the machine froze several more times; the clearest case was 2026-10-04, when the whole screen locked up and the kernel log filled with 312 repetitions of <code>Pageflip timed out! This is a bug in the amdgpu kernel driver</code> - a display-layer commit timeout in the iGPU driver, an upstream bug, unrelated to the X11 dma_fence deadlock and with no reliable trigger. There is no fix yet; the fallback is the REISUB emergency reboot. The corrected conclusion: Wayland fixed the greeter black screen and the X11 fence deadlocks - not every freeze.</p>`,57)])])}const g=a(i,[["render",o]]);export{k as __pageData,g as default};
